from fetcher import fetch

# Mock client that accepts timeout
class MockClient:
    def __init__(self):
        self.timeout_passed = None
    def get(self, url, timeout=None):
        self.timeout_passed = timeout
        return f'response for {url}'

def test_fetch_preserves_args():
    client = MockClient()
    url = 'http://example.com'
    result = fetch(client, url)
    # check timeout was passed
    assert client.timeout_passed == 30, f'Expected timeout 30, got {client.timeout_passed}'
    # check return value matches client.get result
    assert result == 'response for http://example.com'

def test_fetch_exception_propagation():
    class FailingClient:
        def get(self, url, timeout=None):
            raise RuntimeError('network error')
    client = FailingClient()
    url = 'http://example.com'
    try:
        fetch(client, url)
        assert False, 'Should have raised RuntimeError'
    except RuntimeError as e:
        assert str(e) == 'network error'

if __name__ == '__main__':
    test_fetch_preserves_args()
    test_fetch_exception_propagation()
    print('All tests passed')

